function notify(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function shuffled(list){return list.slice().sort(()=>Math.random()-.5)}
function startMatch(){if(owned.length<3){notify('Collect at least three legends to play.');return}match={you:0,rival:0,round:1,hand:shuffled(owned).slice(0,Math.min(5,owned.length)),rivals:shuffled(PLAYERS.map(p=>p.id)),usedRivals:[],picked:null,done:false};showPage('match');renderMatch()}
function renderMatch(){if(!match)return;document.getElementById('yourScore').textContent=match.you;document.getElementById('rivalScore').textContent=match.rival;document.getElementById('roundNumber').textContent=match.round;document.getElementById('yourSlot').innerHTML=match.picked?cardMarkup(player(match.picked)): '<div class="face-down"><div><b>?</b><span>CHOOSE A CARD BELOW</span></div></div>';document.getElementById('rivalSlot').innerHTML=match.currentRival?cardMarkup(player(match.currentRival)):'<div class="face-down"><div><b>?</b><span>WAITING FOR YOUR CALL</span></div></div>';const chooser=document.getElementById('statChooser');chooser.innerHTML=match.picked&&!match.done?Object.keys(STAT_NAMES).map(k=>`<button class="stat-choice" data-stat="${k}">${k}<strong>${player(match.picked).stats[k]}</strong></button>`).join(''):'';document.querySelectorAll('.stat-choice').forEach(b=>b.disabled=!!match.currentRival||match.done);const result=document.getElementById('roundResult');result.classList.toggle('hidden',!match.message);if(match.message){result.className='result-banner '+(match.message.type||'');result.innerHTML=match.message.text+(match.done?` <button class="btn btn-primary" data-action="again">PLAY AGAIN</button> <button class="btn btn-quiet" data-action="clubhouse">CLUBHOUSE</button>`:'')}
const box=document.getElementById('turnBox');box.querySelector('.turn-number').textContent=match.done?'DUEL COMPLETE':match.currentRival?'CALL REVEALED':'PICK YOUR PLAYER';box.querySelector('p').textContent=match.done?'The final whistle. Fancy another duel?':match.currentRival?'Your stat has been called. See how the legends compare.':match.picked?'Choose the stat you think gives your legend the edge.':'Choose a legend from your hand, then choose the stat you think will win the duel.';box.querySelector('.turn-tip').textContent='TIE? Both sides earn a point.';document.getElementById('handHint').textContent=match.done?'DUEL COMPLETE':match.picked?'NOW CALL YOUR STAT':'PICK ONE PLAYER TO PLAY';document.getElementById('handCards').innerHTML=match.hand.map(id=>cardMarkup(player(id),{compact:true,action:'play',selected:match.picked===id})).join('')||'<div class="empty">No players left in your hand.</div>'}
function pickPlayer(id){if(!match||match.done||match.currentRival)return;if(!match.hand.includes(id))return;match.picked=id;renderMatch()}
function callStat(stat){if(!match||!match.picked||match.done||match.currentRival)return;let choices=match.rivals.filter(id=>!match.usedRivals.includes(id));if(!choices.length){match.usedRivals=[];choices=match.rivals}let rivalId=choices[Math.floor(Math.random()*choices.length)],you=player(match.picked),rival=player(rivalId),a=you.stats[stat],b=rival.stats[stat];match.currentRival=rivalId;match.usedRivals.push(rivalId);let outcome=a>b?'win':a<b?'loss':'tie';if(outcome==='win')match.you++;if(outcome==='loss')match.rival++;if(outcome==='tie'){match.you++;match.rival++}match.hand=match.hand.filter(id=>id!==match.picked);let msg=outcome==='win'?`Your ${you.name} takes ${STAT_NAMES[stat]} ${a}–${b} against ${rival.name}. Point to you!`:outcome==='loss'?`${rival.name} edges ${STAT_NAMES[stat]} ${b}–${a}. Point to the rival.`:`A dead heat! ${you.name} and ${rival.name} both earn a point.`;let finished=match.you>=3||match.rival>=3||match.hand.length===0;match.done=finished;if(finished){let final=match.you===match.rival?'A legendary draw.':match.you>match.rival?'Victory! Your legends own the pitch.':'The rival takes this one. Rematch?';if(match.you>match.rival){coins+=65;wins++;persist();updateHeader();final+=' +65 credits';}else if(match.you===match.rival){coins+=25;persist();updateHeader();final+=' +25 credits';}else{coins+=15;persist();updateHeader();final+=' +15 credits';}msg+=` ${final}`;match.message={text:msg,type:match.you>match.rival?'win':match.you<match.rival?'loss':''}}else{match.message={text:msg,type:outcome==='win'?'win':outcome==='loss'?'loss':''}}renderMatch()}
function showPackModal(){if(owned.length===PLAYERS.length){notify('You have collected every legend!');return}if(coins<100){notify('You need 100 credits for a Legend Pack.');return}document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" data-dismiss="true"><section class="modal"><div class="eyebrow">A new name for your wall</div><div class="pack-visual"><b>XI</b></div><h2>Legend Pack</h2><p>One guaranteed new legend from football history. Add another great to your collection for <b style="color:var(--lime)">100 credits</b>.</p><div class="modal-actions"><button class="btn btn-quiet" data-action="cancel">MAYBE LATER</button><button class="btn btn-primary" data-action="buy-pack">OPEN PACK · 100 CR</button></div></section></div>`}
function openPack(){if(owned.length===PLAYERS.length){notify('You have collected every legend!');return}if(coins<100){notify('Not enough credits. Win a duel to earn more.');return}coins-=100;let fresh=PLAYERS.filter(p=>!owned.includes(p.id));let prize=fresh[Math.floor(Math.random()*fresh.length)];owned.push(prize.id);persist();updateHeader();document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" data-dismiss="true"><section class="modal"><div class="eyebrow">Added to your collection</div><h2>${prize.name}</h2><p>Your new ${prize.rarity.toLowerCase()} is ready to take the pitch.</p><div style="width:220px;margin:17px auto">${cardMarkup(prize)}</div><div class="modal-actions"><button class="btn btn-primary" data-action="close-pack">BEAUTIFUL. LET'S GO</button></div></section></div>`;renderHome();renderCollection()}

